files.terminal.css:
/* Terminal: monospaced everything, square corners, dashed rules. */
:root {
  --font-sans: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  --font-heading: var(--font-sans);
  --radius: 0.125rem;
}

body {
  letter-spacing: -0.01em;
}

/* Square surfaces and dashed borders on the main panels. */
[data-bv="sidebar"],
[data-bv="notebook"] [role="tabpanel"],
[data-bv="note-tabs"] {
  border-radius: 0 !important;
  outline: 1px dashed var(--border);
  outline-offset: -1px;
  box-shadow: none !important;
}

[data-bv="sidebar"] {
  background: transparent !important;
}

/* A prompt like a command line. */
[data-bv="prompt"] form,
[data-bv="prompt"] [data-slot] {
  border-radius: 0 !important;
}
[data-bv="prompt"] textarea::placeholder {
  font-family: var(--font-sans);
}

/* Tiles and tools: flat, with a dashed edge. */
[data-bv="studio-tools"] > *,
[data-bv="vault-grid"] .vault-frame {
  border-radius: 0 !important;
  outline: 1px dashed var(--border);
  box-shadow: none !important;
}

/* A blinking caret after headings in dark mode, like a prompt. */
.dark [data-bv="vault-toolbar"] h1::after {
  content: "▌";
  margin-inline-start: 0.25em;
  color: var(--primary);
  animation: terminal-blink 1.1s steps(1) infinite;
}
@keyframes terminal-blink {
  50% {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .dark [data-bv="vault-toolbar"] h1::after {
    animation: none;
  }
}
